import{_ as t,o as i,c as a,ao as s}from"./chunks/framework.De4f9JjF.js";const g=JSON.parse('{"title":"Fitting at scale: exact vs matrix-free","description":"","frontmatter":{},"headers":[],"relativePath":"fitting-at-scale.md","filePath":"fitting-at-scale.md","lastUpdated":null}'),n={name:"fitting-at-scale.md"};function o(r,e,l,d,h,c){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="Fitting-at-scale:-exact-vs-matrix-free" tabindex="-1">Fitting at scale: exact vs matrix-free <a class="header-anchor" href="#Fitting-at-scale:-exact-vs-matrix-free" aria-label="Permalink to &quot;Fitting at scale: exact vs matrix-free {#Fitting-at-scale:-exact-vs-matrix-free}&quot;">​</a></h1><link rel="stylesheet" href="./assets/hs-docs.css"><p><code>HSquared.jl</code> has <strong>two</strong> engines for the <code>K</code>-independent-random-effect mixed model, and <a href="/HSquared.jl/previews/PR289/api#HSquared.fit_multi_effect"><code>fit_multi_effect</code></a> chooses between them by feasibility. This page explains the choice, the accuracy-vs-feasibility trade, and how to control it.</p><div class="warning custom-block"><p class="custom-block-title">Experimental · opt-in · not the default fit</p><p>Everything on this page is experimental and validation-scale. The public default fit path is the univariate Gaussian animal model; these multi-effect engines are opt-in. Timings below are measurements, not a production-performance claim.</p></div><h2 id="The-two-engines" tabindex="-1">The two engines <a class="header-anchor" href="#The-two-engines" aria-label="Permalink to &quot;The two engines {#The-two-engines}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;"></th><th style="text-align:right;">exact</th><th style="text-align:right;">matrix-free</th></tr></thead><tbody><tr><td style="text-align:right;">function</td><td style="text-align:right;"><a href="/HSquared.jl/previews/PR289/api#HSquared.fit_sparse_multi_effect_aireml"><code>fit_sparse_multi_effect_aireml</code></a></td><td style="text-align:right;"><a href="/HSquared.jl/previews/PR289/api#HSquared.fit_multi_effect_mc_reml"><code>fit_multi_effect_mc_reml</code></a></td></tr><tr><td style="text-align:right;">method</td><td style="text-align:right;">sparse AI-REML (exact gradient from a Cholesky <strong>selected inverse</strong>)</td><td style="text-align:right;">Monte-Carlo EM-REML (matrix-free solves + a <strong>Hutchinson stochastic trace</strong>)</td></tr><tr><td style="text-align:right;">forms/factorizes <code>C</code>?</td><td style="text-align:right;"><strong>yes</strong> — a sparse Cholesky each iteration</td><td style="text-align:right;"><strong>no</strong> — only &quot;matrix × vector&quot;</td></tr><tr><td style="text-align:right;">accuracy</td><td style="text-align:right;">exact</td><td style="text-align:right;">approximate — the gradient carries a Monte-Carlo standard error</td></tr><tr><td style="text-align:right;">where it wins</td><td style="text-align:right;">small–moderate size (exact, few iterations)</td><td style="text-align:right;">very large size, where the factorization is infeasible</td></tr></tbody></table><p><strong>Why two?</strong> With a <em>single</em> random effect the animal-model factorization stays sparse and scales to very large pedigrees. But with <em>two or more</em> random effects (a contemporary-group, maternal, or permanent-environment term alongside the animal effect) the sparse Cholesky <strong>fills in</strong> — the factor becomes far denser than <code>C</code> — and past roughly <code>10⁵</code> individuals it becomes infeasible in memory and time (measured: the direct multi-effect path is already ~quadratic by <code>q ≈ 50 000</code>; a METIS reordering did <strong>not</strong> fix it). The matrix-free engine never forms or factorizes <code>C</code>, so it has no fill wall — it has stayed feasible fitting <code>K = 3</code> models to 200 000 individuals in testing (the matrix-free <em>solve</em> it is built on reaches a million) — but it pays with Monte-Carlo noise in the variance-component gradient.</p><p>This is the same accuracy-for-feasibility trade a variational approximation makes: you reach for the approximate engine <strong>only</strong> where the exact one cannot run.</p><h2 id="Choosing-automatically" tabindex="-1">Choosing automatically <a class="header-anchor" href="#Choosing-automatically" aria-label="Permalink to &quot;Choosing automatically {#Choosing-automatically}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fit_multi_effect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(y, X, effects)                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># method = :auto (the default)</span></span></code></pre></div><p><code>:auto</code> routes on feasibility:</p><ul><li><p>a <strong>single</strong> random effect (<code>K = 1</code>), or <code>N = p + Σqᵢ ≤ direct_max_n</code> → <strong>exact</strong>;</p></li><li><p>otherwise → <strong>matrix-free</strong>, printing a one-line <code>@info</code> that it switched and that the estimates carry a Monte-Carlo standard error.</p></li></ul><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fit_multi_effect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(y, X, effects; method </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :exact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># force exact (may run out of memory)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fit_multi_effect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(y, X, effects; method </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :matrix_free</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># force matrix-free (accept MC noise)</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">The <code>:auto</code> threshold is a heuristic</p><p><code>direct_max_n</code> (default <code>200_000</code>) is a <strong>coarse, machine-agnostic</strong> cutoff calibrated to the measured <code>K ≥ 2</code> factorization cost, deliberately conservative and always overridable. It is <strong>not</strong> a precise per-problem fill prediction — that is future work. When in doubt on a large problem, try <code>method = :exact</code> first; if it fits in memory, its answer is exact.</p></div><p>The returned <code>NamedTuple</code> carries a <code>dispatch</code> field (<code>:exact</code> or <code>:matrix_free</code>) recording which engine ran. The two result shapes differ: the matrix-free result has a <code>trace_mcse</code> (and <strong>no</strong> <code>loglik</code> — a matrix-free REML log-likelihood needs a stochastic log-determinant, which is not yet implemented).</p><h2 id="Reading-the-Monte-Carlo-noise" tabindex="-1">Reading the Monte-Carlo noise <a class="header-anchor" href="#Reading-the-Monte-Carlo-noise" aria-label="Permalink to &quot;Reading the Monte-Carlo noise {#Reading-the-Monte-Carlo-noise}&quot;">​</a></h2><p>When the matrix-free engine runs, the fit reports <code>trace_mcse</code> — the Monte-Carlo standard error of the score-trace terms, i.e. the noise you traded for feasibility. It shrinks like <code>1/√nprobe</code> (more probe vectors ⇒ tighter). If you need a tighter answer, raise <code>nprobe</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fit_multi_effect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(y, X, effects; method </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :matrix_free</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, nprobe </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The matrix-free fit <strong>reproduces</strong> the exact AI-REML variance components as <code>nprobe</code> grows: in the recovery gate it tracks the exact estimator on identical data, with the Monte-Carlo perturbation controllable by <code>nprobe</code>.</p><h2 id="Honest-scope" tabindex="-1">Honest scope <a class="header-anchor" href="#Honest-scope" aria-label="Permalink to &quot;Honest scope {#Honest-scope}&quot;">​</a></h2><ul><li><p>These engines fit <strong>variance components + BLUPs</strong> for <code>K</code> independent Gaussian random effects. They are not the public default, not calibrated-interval methods, and the matrix-free engine is a supplied-machinery estimator whose scale evidence is machine-specific (see the validation-status page and the v0.8 recovery-checkpoints).</p></li><li><p>The exact engine&#39;s small-sample recovery is the covered <code>V3-NEFFECT-REML</code> result. The matrix-free engine&#39;s added claim is only that its Monte-Carlo approximation <strong>reproduces</strong> that exact fit.</p></li></ul>`,21)])])}const f=t(n,[["render",o]]);export{g as __pageData,f as default};
